import { useState } from 'react';
import { JxTagInput } from '@jinx-ui/react';

interface ArticleTagsFieldProps {
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagsField({ defaultTags = [], onChange }: ArticleTagsFieldProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const handleValueChange = (value: string[]) => {
    setTags(value);
    onChange?.(value);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-xs)',
      }}
    >
      <label
        htmlFor="article-tags-input"
        style={{
          fontFamily: 'var(--jx-font-sans)',
          fontSize: '0.875rem',
          color: 'var(--jx-text-2)',
        }}
      >
        Теги статьи
      </label>
      <JxTagInput
        ariaLabel="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={handleValueChange}
      />
    </div>
  );
}

